import assert from 'node:assert/strict'
import { test } from 'node:test'

import { searchPageMarkup } from '../src/SearchPage.js'
import { settingsPageMarkup } from '../src/SettingsPage.js'

test('both assembled consumers use the shared button', () => {
  assert.match(searchPageMarkup(), /class="button primary"/)
  const settings = settingsPageMarkup({ saving: true })
  assert.match(settings, /class="button secondary"/)
  assert.match(settings, /class="button danger" type="button" disabled/)
})
import assert from 'node:assert/strict'
import { test } from 'node:test'

import { classifyWorkerFailure, projectWorkerFailure } from '../src/worker-client.js'

const result = {
  error: {
    kind: 'permission_denied',
    detail: { scope: 'repository' },
    message: 'permission problem',
  },
}

test('the worker boundary preserves and observes the machine identity', () => {
  const projected = projectWorkerFailure(result)
  assert.deepEqual(projected, result.error)
  assert.equal(classifyWorkerFailure(projected), 'request-access')
})

